import os, base64

FILES = {
    '__init__.py': '',
    'admin.py': '',
    'models.py': '',
    'forms.py': '',
    'views.py': '',
    'urls.py': '',
    'utils.py': '',
    'static/quotations/css/quotations.css': '',
    'migrations/__init__.py': '',
    'templates/quotations/admin_quote_list.html': '',
    'templates/quotations/admin_quote_detail.html': '',
    'templates/quotations/quote_detail.html': '',
    'templates/quotations/quote_form.html': '',
}

for rel_path, b64content in FILES.items():
    full_path = os.path.join('quotations', rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, 'wb') as f:
        f.write(base64.b64decode(b64content))
    print('Created:', full_path)

print()
print('DONE! quotations app successfully created.')